import { readFile, stat } from "node:fs/promises";

import { Effect, Schema } from "effect";

import {
  preflightProductionPromotion,
  ProductionPreflightSnapshot,
} from "../agent/production-preflight.js";

const snapshotPath = process.argv[2];

if (snapshotPath === undefined) {
  throw new Error("Usage: production-preflight <mode-0600-snapshot.json>");
}

await Effect.runPromise(
  Effect.gen(function* productionPreflightCommand() {
    const metadata = yield* Effect.tryPromise({
      try: () => stat(snapshotPath),
      catch: () =>
        new Error("Unable to read the Production preflight metadata snapshot."),
    });

    if ((metadata.mode & 0o777) !== 0o600) {
      return yield* Effect.fail(
        new Error("Production preflight metadata must have mode 0600."),
      );
    }

    const content = yield* Effect.tryPromise({
      try: () => readFile(snapshotPath, "utf8"),
      catch: () =>
        new Error("Unable to read the Production preflight metadata snapshot."),
    });
    const snapshot = yield* Schema.decodeUnknownEffect(
      Schema.fromJsonString(ProductionPreflightSnapshot)
    )(content);
    const evidence = yield* preflightProductionPromotion(snapshot);

    process.stdout.write(
      yield* Schema.encodeEffect(
        Schema.fromJsonString(
          (await import("../agent/production-preflight.js"))
            .ProductionPreflightEvidence
        )
      )(evidence)
    );
  })
);

